using Captovix;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
internal static class Program
{
 [STAThread]static int Main(){try{int n=0;void Check(bool v,string message){if(!v)throw new Exception(message);n++;Console.WriteLine("PASS: "+message);}bool Near(double a,double b)=>Math.Abs(a-b)<1e-4;
 var app=new App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var pixels=Enumerable.Repeat((byte)255,400*300*4).ToArray();var bitmap=ImageTransfer.Bitmap(400,300,pixels);
 var doc=new EditorDocument{OriginalWidth=400,OriginalHeight=300,Appearance=CanvasEditing.Expand(new(0,0,400,300),new(),100,80,40,20)};var a=new Annotation{Kind=AnnotationKind.Rectangle,X1=30,Y1=40,X2=130,Y2=100,FillEnabled=true};var b=a.Copy();b.Id=Guid.NewGuid().ToString("N");b.X1=60;b.Y1=55;b.X2=160;b.Y2=115;doc.Annotations=[a,b];var session=new EditorSession(doc);var surface=new EditorSurface();surface.Load(bitmap,session);surface.Tool=EditorTool.Select;
 var hits=surface.HitStack(new(80,70));Check(hits.Length==2&&hits[0].Id==b.Id,"Overlapping hit stack follows actual paint order");b.Visible=false;Check(surface.HitStack(new(80,70)).Length==1,"Hidden layer never appears in hit stack");b.Visible=true;b.Locked=true;Check(surface.HitStack(new(80,70)).Length==1&&surface.HitStack(new(80,70),true).Length==2,"Locked layer is selectable via context stack without becoming draggable");b.Locked=false;
 var frame=ObjectPrecision.Frame(doc,[a.Id],EditorRenderer.Box);int width=surface.Flatten().PixelWidth;ObjectPrecision.ApplyFrame(doc,[a.Id],25,35,frame.Width*2,frame.Height*2,0,EditorRenderer.Box,EditorRenderer.LocalBox);var changed=ObjectPrecision.Frame(doc,[a.Id],EditorRenderer.Box);Check(Near(changed.X,25)&&Near(changed.Y,35)&&Near(changed.Width,frame.Width*2),"Real renderer bounds match numeric output frame");Check(surface.Flatten().PixelWidth==width,"Object editing keeps output dimensions");
 var frozen=doc.Clone();var image1=surface.Flatten();surface.SetZoom(.25);var image2=surface.Flatten();Check(ImageTransfer.Bgra(image1).SequenceEqual(ImageTransfer.Bgra(image2)),"Editor zoom does not change exported pixels");
 surface.SelectIds([a.Id]);var before=ObjectPrecision.Frame(doc,[a.Id],EditorRenderer.Box);surface.Nudge(1,0);var nudged=ObjectPrecision.Frame(session.Document,[a.Id],EditorRenderer.Box);Check(Near(nudged.X,before.X+1),"Arrow nudge is one output pixel");session.Undo();Check(Near(ObjectPrecision.Frame(session.Document,[a.Id],EditorRenderer.Box).X,before.X),"Nudge Undo restores position");
 var resizeDoc=new EditorDocument{OriginalWidth=400,OriginalHeight=300,Annotations=[new(){Kind=AnnotationKind.Rectangle,X1=100,Y1=100,X2=180,Y2=140}]};var resizeSession=new EditorSession(resizeDoc);surface.Load(bitmap,resizeSession);surface.Tool=EditorTool.Select;surface.SetZoom(1);surface.KeepAspectRatio=true;var shape=resizeDoc.Annotations[0];surface.SelectIds([shape.Id]);surface.PointerDown(new(182,142));surface.PointerMove(new(222,162));surface.PointerUp(new(222,162));Check(Near(shape.Width/shape.Height,2),"Mouse resize keeps ratio from checkbox");Check(Near(shape.X1,100)&&Near(shape.Y1,100),"Corner resize retains opposite handle despite click offset");
 var groupDoc=new EditorDocument{OriginalWidth=400,OriginalHeight=300,Annotations=[new(){Kind=AnnotationKind.Rectangle,X1=20,Y1=20,X2=60,Y2=60},new(){Kind=AnnotationKind.Rectangle,X1=80,Y1=80,X2=120,Y2=120}]};AnnotationEditing.Group(groupDoc,groupDoc.Annotations.Select(x=>x.Id));var groupSession=new EditorSession(groupDoc);surface.Load(bitmap,groupSession);surface.Tool=EditorTool.Select;surface.SelectIds([groupDoc.Annotations[0].Id]);surface.Nudge(10,0);Check(groupDoc.Annotations.All(x=>x.X1 is 30 or 90),"Group keyboard move includes all members");Check(groupDoc.Appearance.CanvasWidth==0&&groupDoc.Appearance.ExtendLeft==0,"Moving group never silently grows canvas");
 var frameDoc=new EditorDocument{OriginalWidth=400,OriginalHeight=300,Appearance=new(){CanvasWidth=100,CanvasHeight=80,BorderWidth=10,BorderColor="#101010",DrawOutsideImage=true}};var frameLayout=new ImageLayout(frameDoc.Viewport,frameDoc.Appearance);var location=frameLayout.ToSource(0,0);frameDoc.Annotations=[new(){Kind=AnnotationKind.Rectangle,X1=location.X,Y1=location.Y,X2=location.X+8,Y2=location.Y+8,FillEnabled=true,FillColor="#FF0000",StrokeEnabled=false}];var frameBitmap=EditorRenderer.Render(bitmap,frameDoc);var frameBytes=ImageTransfer.Bgra(frameBitmap);Check(frameBytes[(2*frameBitmap.PixelWidth+2)*4+2]>240,"Outside opt-in annotation can occupy outer frame pixels");Check(frameBytes[(50*frameBitmap.PixelWidth+2)*4+2]<40,"Original image stays clipped inside its frame despite expanded annotation area");
 Console.WriteLine($"{n} object precision Windows checks passed. Live mouse, menu, DPI and installation acceptance still required.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
